def find_max(words):
    if not words:
        return ""

    best = words[0]
    best_unique = len(set(best))

    for word in words[1:]:
        unique = len(set(word))
        if unique > best_unique:
            best = word
            best_unique = unique
        elif unique == best_unique:
            if word < best:
                best = word

    return best
```

